Array getExtendedMemcacheStats(const String& type = String(), int slabid = 0, int limit = 0) {
    Memcached::Stats stats;
    Array result;

    if (!Memcached::getExtendedStats(stats, type, slabid, limit)) {
        return Array();
    }

    for (const auto& serverStats : stats) {
        String key = serverStats.host + ":" + std::to_string(serverStats.port);
        result.set(key, serverStats.data);
    }

    Memcached::freeStats(stats);
    return result;
}

