// Assuming the existence of the following helper classes and functions as per logic:
// - Memcache::getExtendedStats(): retrieves raw stats
// - MemcacheExtendedStats::iterator: allows iterating over server stats
// - MemcacheExtendedStats::free(): deallocates memory
// - MemcacheExtendedStats::isSuccess(): checks if retrieval succeeded

using namespace std;
using __gnu_cxx::hash_map;

hash_map<string, hash_map<string, string>> getExtendedMemcacheStats(const string& type, int slabid = 0, int limit = 0) {
    hash_map<string, hash_map<string, string>> result;
    MemcacheExtendedStats stats = Memcache::getExtendedStats(type);

    if (!stats.isSuccess()) {
        return result; // Return empty array on failure
    }

    int count = 0;
    for (MemcacheExtendedStats::iterator it = stats.begin(); it != stats.end() && (limit <= 0 || count < limit); ++it, ++count) {
        const string& hostname = it->hostname();
        int port = it->port();
        const hash_map<string, string>& serverStats = it->getStats();

        // Filter by slabid if provided
        if (slabid > 0) {
            bool hasSlabStats = false;
            for (const auto& entry : serverStats) {
                if (entry.first.find("slab") != string::npos && stoi(entry.first.substr(4)) == slabid) {
                    hasSlabStats = true;
                    break;
                }
            }
            if (!hasSlabStats) {
                continue;
            }
        }

        string serverKey = hostname + ":" + to_string(port);
        result.insert({serverKey, serverStats});
    }

    stats.free();
    return result;
}
